extends "res://htd/htd_test.gd"

func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main_caricato", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var enemy := find_by_name(main, "Enemy") as CharacterBody2D
	if not check("nemico_presente", enemy != null, "Serve un CharacterBody2D chiamato Enemy nella scena"):
		return
	var agent := find_by_class(enemy, "NavigationAgent2D") as NavigationAgent2D
	if not check("agent_presente", agent != null, "Enemy deve avere un NavigationAgent2D come figlio"):
		return
	var timer := find_by_name(enemy, "PathTimer") as Timer
	if not check("timer_presente", timer != null, "Enemy deve avere un Timer chiamato PathTimer"):
		return
	check("timer_autostart", timer.autostart, "PathTimer deve avere autostart attivo")
	check("timer_wait_time", is_equal_approx(timer.wait_time, 0.2), "PathTimer deve avere wait_time impostato a 0.2")
	# Portiamo il nemico in inseguimento forzando lo stato se possibile o posizionando vicino al player
	var player := find_by_name(main, "Player") as Node2D
	if player != null:
		enemy.global_position = Vector2(120, 80)
		player.global_position = Vector2(160, 80)
		await wait_physics_frames(10)
		check("inseguimento_movimento", enemy.velocity.length() > 0.0 or agent.is_navigation_finished(), "Il nemico in stato CHASE deve calcolare velocità tramite il percorso")

