extends CharacterBody2D

@export var speed: float = 120.0
@export var target: Node2D

@onready var navigation_agent: NavigationAgent2D = $NavigationAgent2D
@onready var path_timer: Timer = $PathTimer


func _ready() -> void:
	path_timer.timeout.connect(_on_path_timer_timeout)
	# Rimanda la configurazione al primo fotogramma utile per attendere il server.
	_setup_navigation.call_deferred()


func _setup_navigation() -> void:
	# Attende che il NavigationServer2D abbia sincronizzato le tessere della mappa.
	await get_tree().physics_frame
	_update_target_path()


func _physics_process(_delta: float) -> void:
	if navigation_agent.is_navigation_finished():
		velocity = Vector2.ZERO
		return

	var next_position: Vector2 = navigation_agent.get_next_path_position()
	var direction: Vector2 = global_position.direction_to(next_position)

	velocity = direction * speed
	move_and_slide()


func _update_target_path() -> void:
	if target != null:
		navigation_agent.target_position = target.global_position


func _on_path_timer_timeout() -> void:
	_update_target_path()
